import{_ as a,C as s,c as r,o as c,a3 as e,G as n}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Chart of accounts","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/get-started/chart-of-accounts.md","filePath":"master/finance/get-started/chart-of-accounts.md","lastUpdated":1793074831000}'),i={name:"master/finance/get-started/chart-of-accounts.md"};function l(u,t,h,d,g,p){const o=s("ImagePopup");return c(),r("div",null,[t[0]||(t[0]=e('<h1 id="chart-of-accounts" tabindex="-1">Chart of accounts <a class="header-anchor" href="#chart-of-accounts" aria-label="Permalink to &quot;Chart of accounts&quot;">​</a></h1><p>The chart of accounts is the full list of accounts your company uses to record money. Every invoice, bill and payment ends up as debit and credit lines on these accounts. Reports such as the balance sheet and the profit and loss are built from them.</p><blockquote><p><strong>In simple words:</strong> An account is a labelled bucket for money, such as &quot;Bank&quot;, &quot;Product Sales&quot; or &quot;Rent&quot;. The chart of accounts is the list of all buckets.</p></blockquote><h2 id="when-to-use-this-page" tabindex="-1">When to use this page <a class="header-anchor" href="#when-to-use-this-page" aria-label="Permalink to &quot;When to use this page&quot;">​</a></h2><ul><li>You need a new account, for example a separate expense account for travel.</li><li>You want to check which account an amount went to.</li><li>You want to stop using an account without deleting it.</li></ul><h2 id="open-the-page" tabindex="-1">Open the page <a class="header-anchor" href="#open-the-page" aria-label="Permalink to &quot;Open the page&quot;">​</a></h2><p>Go to <code>Accounting → Configurations → Accounting → Chart of Accounts</code>. This page exists only in the <strong>Accounting</strong> app.</p>',7)),n(o,{src:"/images1/finance/chart_of_accounts_list.png",alt:"Accounting → Configurations → Accounting → Chart of Accounts, showing the code tabs, the type tabs and the first rows"}),t[1]||(t[1]=e('<h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows the accounts of the current company, 25 per page.</p><ul><li><strong>Code:</strong> the account number, for example <code>101000</code>.</li><li><strong>Account Name:</strong> the name, for example <code>Current Assets</code>.</li><li><strong>Account:</strong> the account type, for example Current Assets.</li><li><strong>Parent Account:</strong> the account this one sits under.</li><li><strong>Allow Reconcile:</strong> <strong>Yes</strong> if payments can be matched against it.</li><li><strong>Currency:</strong> the account currency.</li></ul><h3 id="find-an-account" tabindex="-1">Find an account <a class="header-anchor" href="#find-an-account" aria-label="Permalink to &quot;Find an account&quot;">​</a></h3><ul><li><strong>Code tabs:</strong> the number tabs (1, 2, 3 and so on) show only accounts whose code starts with that digit. Click <strong>All</strong> to remove the filter.</li><li><strong>Type tabs:</strong> <strong>Receivable</strong>, <strong>Payable</strong>, <strong>Equity</strong>, <strong>Assets</strong>, <strong>Liability</strong>, <strong>Income</strong> and <strong>Expenses</strong> show accounts of those types. <strong>Default</strong> shows all.</li><li><strong>Search:</strong> type a code or a name.</li><li><strong>Group by:</strong> choose <strong>Account type</strong> to group the rows by type.</li><li><strong>Filters:</strong> <strong>Account Type</strong>, <strong>Parent Account</strong>, <strong>Journals</strong>, <strong>Currency</strong>, <strong>Allow Reconcile</strong> and <strong>Non Trade</strong>.</li></ul><p>To learn more about searching, see <a href="./../../getting-started/search-filter-group.html">Search, filter and group</a>.</p><h2 id="create-an-account" tabindex="-1">Create an account <a class="header-anchor" href="#create-an-account" aria-label="Permalink to &quot;Create an account&quot;">​</a></h2><ol><li>Go to <code>Accounting → Configurations → Accounting → Chart of Accounts</code>.</li><li>Click <strong>New Chart of Account</strong>. A window opens.</li><li>Fill in the fields below.</li><li>Click <strong>Create</strong>.</li></ol>',8)),n(o,{src:"/images1/finance/chart_of_accounts_form.png",alt:"The New Chart of Account window filled with Code 600100, Account Name Travel Expenses, Account Type Expenses, Companies My Company"}),t[2]||(t[2]=e('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Code:</em></strong> A unique number for the account. Two accounts cannot share a code. Group related accounts with the same first digits, such as <code>6001</code> for all travel costs.</li><li><strong><em>Account Name:</em></strong> The name people will see in lists and reports.</li></ul><h3 id="accounting" tabindex="-1">Accounting <a class="header-anchor" href="#accounting" aria-label="Permalink to &quot;Accounting&quot;">​</a></h3><ul><li><strong><em>Account Type:</em></strong> What the account is for. This is required. The type decides where it appears in reports. See the table below.</li><li><strong><em>Parent Account:</em></strong> Choose an existing account to make this one a sub-account. Leave it empty for a top level account.</li><li><strong><em>Default Taxes:</em></strong> Taxes proposed when this account is used on a line. Hidden for <strong>Off-Balance Sheet</strong> accounts.</li><li><strong><em>Tags:</em></strong> Labels you can attach to group accounts in your own way.</li><li><strong><em>Journals:</em></strong> The journals that may use this account. Aureus suggests journals when you pick the type, for example Sale journals for an <strong>Income</strong> account. You can change the suggestion.</li><li><strong><em>Currency:</em></strong> Fix the account to one active currency. Leave it empty if the account can hold any currency.</li><li><strong><em>Companies:</em></strong> The companies that can use the account. This is required.</li><li><strong><em>Deprecated:</em></strong> Turn on to stop using the account. It will no longer be offered in the pickers for default and journal accounts.</li><li><strong><em>Allow Reconcile:</em></strong> Turn on if you want to match payments against this account. Receivable and payable accounts usually need it.</li><li><strong><em>Non Trade:</em></strong> Turn on for receivable or payable accounts that are not about customers or vendors, such as staff advances.</li></ul><h3 id="account-types" tabindex="-1">Account types <a class="header-anchor" href="#account-types" aria-label="Permalink to &quot;Account types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Group</th><th>Types</th></tr></thead><tbody><tr><td>Assets</td><td>Receivable, Bank and Cash, Current Assets, Non-current Assets, Prepayments, Fixed Assets</td></tr><tr><td>Liabilities</td><td>Payable, Credit Card, Current Liabilities, Non-current Liabilities</td></tr><tr><td>Equity</td><td>Equity, Current Year Earnings</td></tr><tr><td>Income</td><td>Income, Other Income</td></tr><tr><td>Expenses</td><td>Expenses, Depreciation, Cost of Revenue</td></tr><tr><td>Other</td><td>Off-Balance Sheet</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>You want to track flights separately. Create an account with <strong>Code</strong> <code>600100</code>, <strong>Account Name</strong> <code>Travel Expenses</code>, <strong>Account Type</strong> <code>Expenses</code>. Choose your company under <strong>Companies</strong>. Now you can pick it on a vendor bill line or as a product expense account.</p><h2 id="edit-view-and-delete" tabindex="-1">Edit, view and delete <a class="header-anchor" href="#edit-view-and-delete" aria-label="Permalink to &quot;Edit, view and delete&quot;">​</a></h2><p>Each row has <strong>View</strong>, <strong>Edit</strong> and <strong>Delete</strong>. <strong>Edit</strong> opens the same form.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>You cannot delete an account that has journal items. Aureus shows &quot;Account deletion failed&quot; and keeps it. Turn on <strong>Deprecated</strong> instead. Bulk delete follows the same rule.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./journals.html">Journals</a></li><li><a href="./default-accounts.html">Default accounts</a></li><li><a href="./../accounting-entries/journal-items.html">Journal items</a></li><li><a href="./accounting-setup.html">Set up accounting</a></li></ul>',13))])}const b=a(i,[["render",l]]);export{f as __pageData,b as default};
